    26→/// An error occurred while validating a gossip data column.
    27→#[derive(Debug)]
    28→pub enum GossipDataColumnError {
    29→    /// There was an error whilst processing the data column. It is not known if it is
    30→    /// valid or invalid.
    31→    ///
    32→    /// ## Peer scoring
    33→    ///
    34→    /// We were unable to process this data column due to an internal error. It's
    35→    /// unclear if the data column is valid.
    36→    BeaconChainError(Box<BeaconChainError>),
    37→    /// The proposal signature in invalid.
    38→    ///
    39→    /// ## Peer scoring
    40→    ///
    41→    /// The data column is invalid and the peer is faulty.
    42→    ProposalSignatureInvalid,
    43→    /// The proposal_index corresponding to data column.beacon_block_root is not known.
    44→    ///
    45→    /// ## Peer scoring
    46→    ///
    47→    /// The data column is invalid and the peer is faulty.
    48→    UnknownValidator(u64),
    49→    /// The provided data column is not from a later slot than its parent.
    50→    ///
    51→    /// ## Peer scoring
    52→    ///
    53→    /// The data column is invalid and the peer is faulty.
    54→    IsNotLaterThanParent {
    55→        data_column_slot: Slot,
    56→        parent_slot: Slot,
    57→    },
    58→    /// The kzg verification failed.
    59→    ///
    60→    /// ## Peer scoring
    61→    ///
    62→    /// The data column sidecar is invalid and the peer is faulty.
    63→    InvalidKzgProof(kzg::Error),
    64→    /// The column was gossiped over an incorrect subnet.
    65→    ///
    66→    /// ## Peer scoring
    67→    ///
    68→    /// The column is invalid or the peer is faulty.
    69→    InvalidSubnetId { received: u64, expected: u64 },
    70→    /// The column sidecar is from a slot that is later than the current slot (with respect to the
    71→    /// gossip clock disparity).
    72→    ///
    73→    /// ## Peer scoring
    74→    ///
    75→    /// Assuming the local clock is correct, the peer has sent an invalid message.
    76→    FutureSlot {
    77→        message_slot: Slot,
    78→        latest_permissible_slot: Slot,
    79→    },
    80→    /// The sidecar corresponds to a slot older than the finalized head slot.
    81→    ///
    82→    /// ## Peer scoring
    83→    ///
    84→    /// It's unclear if this column is valid, but this column is for a finalized slot and is
    85→    /// therefore useless to us.
    86→    PastFinalizedSlot {
    87→        column_slot: Slot,
    88→        finalized_slot: Slot,
    89→    },
    90→    /// The pubkey cache timed out.
    91→    ///
    92→    /// ## Peer scoring
    93→    ///
    94→    /// The column sidecar may be valid, this is an internal error.
    95→    PubkeyCacheTimeout,
    96→    /// The proposer index specified in the sidecar does not match the locally computed
    97→    /// proposer index.
    98→    ///
    99→    /// ## Peer scoring
   100→    ///
   101→    /// The column is invalid and the peer is faulty.
   102→    ProposerIndexMismatch { sidecar: usize, local: usize },
   103→    /// The provided columns's parent block is unknown.
   104→    ///
   105→    /// ## Peer scoring
   106→    ///
   107→    /// We cannot process the columns without validating its parent, the peer isn't necessarily faulty.
   108→    ParentUnknown { parent_root: Hash256 },
   109→    /// The column conflicts with finalization, no need to propagate.
   110→    ///
   111→    /// ## Peer scoring
   112→    ///
   113→    /// It's unclear if this column is valid, but it conflicts with finality and shouldn't be
   114→    /// imported.
   115→    NotFinalizedDescendant { block_parent_root: Hash256 },
   116→    /// Invalid kzg commitment inclusion proof
   117→    ///
   118→    /// ## Peer scoring
   119→    ///
   120→    /// The column sidecar is invalid and the peer is faulty
   121→    InvalidInclusionProof,
   122→    /// A column has already been seen for the given `(sidecar.block_root, sidecar.index)` tuple
   123→    /// over gossip or no gossip sources.
   124→    ///
   125→    /// ## Peer scoring
   126→    ///
   127→    /// The peer isn't faulty, but we do not forward it over gossip.
   128→    PriorKnown {
   129→        proposer: u64,
   130→        slot: Slot,
   131→        index: ColumnIndex,
   132→    },
   133→    /// A column has already been processed from non-gossip source and have not yet been seen on
   134→    /// the gossip network.
   135→    /// This column should be accepted and forwarded over gossip.
   136→    PriorKnownUnpublished,
   137→    /// Data column index must be between 0 and `NUMBER_OF_COLUMNS` (exclusive).
   138→    ///
   139→    /// ## Peer scoring
   140→    ///
   141→    /// The column sidecar is invalid and the peer is faulty
   142→    InvalidColumnIndex(u64),
   143→    /// Data column not expected for a block with empty kzg commitments.
   144→    ///
   145→    /// ## Peer scoring
   146→    ///
   147→    /// The column sidecar is invalid and the peer is faulty
   148→    UnexpectedDataColumn,
   149→    /// The data column length must be equal to the number of commitments, otherwise the
   150→    /// sidecar is invalid.
   151→    ///
   152→    /// ## Peer scoring
   153→    ///
   154→    /// The column sidecar is invalid and the peer is faulty
   155→    InconsistentCommitmentsLength {
   156→        cells_len: usize,
   157→        commitments_len: usize,
   158→    },
   159→    /// The data column length must be equal to the number of proofs, otherwise the
   160→    /// sidecar is invalid.
   161→    ///
   162→    /// ## Peer scoring
   163→    ///
   164→    /// The column sidecar is invalid and the peer is faulty
   165→    InconsistentProofsLength { cells_len: usize, proofs_len: usize },
   166→}
