   299→impl<E: EthSpec> KzgVerifiedDataColumn<E> {
   300→    pub fn new(
   301→        data_column: Arc<DataColumnSidecar<E>>,
   302→        kzg: &Kzg,
   303→    ) -> Result<Self, (Option<ColumnIndex>, KzgError)> {
