   317→
   318→    pub fn from_batch_with_scoring(
   319→        data_columns: Vec<Arc<DataColumnSidecar<E>>>,
   320→        kzg: &Kzg,
   321→    ) -> Result<Vec<Self>, (Option<ColumnIndex>, KzgError)> {
   322→        verify_kzg_for_data_column_list(data_columns.iter(), kzg)?;
   323→        Ok(data_columns
   324→            .into_iter()
   325→            .map(|column| Self { data: column })
   326→            .collect())
   327→    }
   328→
   329→    pub fn to_data_column(self) -> Arc<DataColumnSidecar<E>> {
   330→        self.data
   331→    }
