   653→    // before doing proposer shuffling calculation via `OnceCell::get_or_try_init`. This avoids
   654→    // holding the lock during the computation, while still ensuring the result is cached and
   655→    // initialised only once.
   656→    //
   657→    // This approach exposes the cache internals (`OnceCell` & `EpochBlockProposers`)
   658→    //  as a trade-off for avoiding lock contention.
   659→    let epoch_proposers_cell = chain
   660→        .beacon_proposer_cache
   661→        .lock()
   662→        .get_or_insert_key(column_epoch, proposer_shuffling_root);
